using System;using System.Linq;using System.Collections.Generic;using UnityEngine;
public static partial class MiamiClothingBuild {
static float GunArea(Vector2[] pts){float a=0;for(int i=0;i<pts.Length;i++){var p=pts[i];var q=pts[(i+1)%pts.Length];a+=p.x*q.y-q.x*p.y;}return a*.5f;}
static void GunBeveled(G g,string text,Vector3 c,float height,bool red,float width){var word=words.words.Single(w=>w.text==text);var all=word.loops.SelectMany(l=>l.points).ToArray();float minx=all.Min(p=>p.x),maxx=all.Max(p=>p.x),miny=all.Min(p=>p.y),maxy=all.Max(p=>p.y),scale=height/(maxy-miny);float sx=width>0?width/(maxx-minx):scale;var outer=word.loops.Select(l=>l.points.Select(p=>new Vector2(-(p.x-(minx+maxx)*.5f)*sx,((miny+maxy)*.5f-p.y)*scale)).ToArray()).ToArray();float orient=Mathf.Sign(GunArea(outer.OrderByDescending(l=>Mathf.Abs(GunArea(l))).First()));float bevel=Mathf.Min(.025f,height*.025f);var inner=new List<Vector2[]>();var frontUV=red?RedUV:Pal(4).center;int frontKind=red?10:2;var edgeUV=red?RedUV:Pal(4).center;
foreach(var loop in outer){var ins=new Vector2[loop.Length];for(int i=0;i<loop.Length;i++){var p=loop[i];var a=(p-loop[(i+loop.Length-1)%loop.Length]).normalized;var b=(loop[(i+1)%loop.Length]-p).normalized;var n0=new Vector2(-a.y,a.x)*orient;var n1=new Vector2(-b.y,b.x)*orient;var n=(n0+n1).normalized;float m=Mathf.Min(bevel*2,bevel/Mathf.Max(.5f,Vector2.Dot(n,n0)));ins[i]=p+n*m;}inner.Add(ins);for(int i=0;i<loop.Length;i++){int j=(i+1)%loop.Length;var a=c+new Vector3(loop[i].x,loop[i].y,0);var b=c+new Vector3(loop[j].x,loop[j].y,0);var aa=a+Vector3.forward*.18f;var bb=b+Vector3.forward*.18f;var ia=c+new Vector3(ins[i].x,ins[i].y,.225f);var ib=c+new Vector3(ins[j].x,ins[j].y,.225f);var side=Pal(7).center;g.Tri(a,b,bb,side,side,side,0);g.Tri(a,bb,aa,side,side,side,0);g.Tri(a,bb,b,side,side,side,0);g.Tri(a,aa,bb,side,side,side,0);g.Tri(aa,bb,ib,edgeUV,edgeUV,edgeUV,red?10:7);g.Tri(aa,ib,ia,edgeUV,edgeUV,edgeUV,red?10:7);g.Tri(aa,ib,bb,edgeUV,edgeUV,edgeUV,red?10:7);g.Tri(aa,ia,ib,edgeUV,edgeUV,edgeUV,red?10:7);}}
var rows=inner.SelectMany(l=>l).Select(p=>p.y).Distinct().OrderBy(y=>y).ToArray();for(int k=1;k<rows.Length;k++){float lo=rows[k-1],hi=rows[k],mid=(lo+hi)*.5f;if(hi-lo<1e-6)continue;var edges=new List<Edge>();foreach(var loop in inner)for(int i=0;i<loop.Length;i++){var a=loop[i];var b=loop[(i+1)%loop.Length];if((a.y<mid&&b.y>mid)||(a.y>mid&&b.y<mid))edges.Add(new Edge{a=a,b=b});}edges=edges.OrderBy(e=>e.X(mid)).ToList();for(int i=1;i<edges.Count;i+=2){var a=edges[i-1];var b=edges[i];var p0=c+new Vector3(a.X(lo),lo,.225f);var p1=c+new Vector3(b.X(lo),lo,.225f);var p2=c+new Vector3(b.X(hi),hi,.225f);var p3=c+new Vector3(a.X(hi),hi,.225f);g.Tri(p0,p1,p2,frontUV,frontUV,frontUV,frontKind);g.Tri(p0,p2,p3,frontUV,frontUV,frontUV,frontKind);}}
}
}

